Repair.source:
class Repair(_Strict):
    schema_id: Literal["terminal-repair/1"] = Field(alias="schema")
    predecessor_checkpoint_sha256: Digest
    source_evidence: list[SourceEvidence] = Field(min_length=1, max_length=128)
    suppress: list[Suppression] = Field(max_length=128)
    add: list[AddedTerm] = Field(max_length=128)
    _file_sha256: str | None = PrivateAttr(default=None)
    _resume_session: str | None = PrivateAttr(default=None)
    _document_sha256: str | None = PrivateAttr(default=None)

    @model_validator(mode="after")
    def sparse_unique(self):
        if not self.suppress and not self.add:
            raise ValueError("empty terminal repair")
        for rows in (self.suppress, self.add):
            keys = [(row.session, row.security_id) for row in rows]
            if len(keys) != len(set(keys)):
                raise ValueError("duplicate terminal repair identity")
        return self

    @property
    def earliest_affected_session(self):
        return min(row.session for row in (*self.suppress, *self.add))

    @property
    def sha256(self):
        return self._file_sha256

