def _apply_spinoff_repair(packet, repair):
    """Review one in-kind event; preserve all prices and suppress its cash proxy."""
    session = _session(packet.day)
    if session <= repair._resume_session or session != repair.earliest_affected_session:
        return packet
    original = tuple(packet.spins)
    if any(row.session != session for row in original):
        raise ValueError("misdated original spinoff")
    suppress = {row.term_sha256 for row in repair.suppress}
    actual = [_digest(asdict(row)) for row in original]
    if len(actual) != len(set(actual)) or not suppress <= set(actual):
        raise ValueError("suppressed original spinoff differs")
    remaining = [row for row, digest in zip(original, actual) if digest not in suppress]
    if any(row.parent_security_id == "224580439420294771" for row in remaining):
        raise ValueError("unsuppressed GE distribution would duplicate economics")
    by_id = {bar.security_id: bar for bar in packet.bars}
    if len(by_id) != len(packet.bars):
        raise ValueError("duplicate spinoff opening bar")
    parent = by_id.get("224580439420294771")
    child = by_id.get("37439132904117100")
    if (parent is None or child is None
            or _digest(asdict(parent)) != repair.parent_bar_sha256
            or _digest(asdict(child)) != repair.child_bar_sha256):
        raise ValueError("spinoff source opening bar differs")
    if (parent.session != session or child.session != session
            or parent.ticker != "GE" or child.ticker != "GEV"
            or not child.tradeable or child.raw_open is None):
        raise ValueError("spinoff source opening identity differs")
    if Decimal(str(parent.dividend_per_share)) != Decimal(repair.cash_proxy_per_parent):
        raise ValueError("spinoff cash proxy differs")
    if Decimal(repair.add[0].cash_in_lieu_price) != Decimal(str(child.raw_open)):
        raise ValueError("CIL research proxy must equal retained child raw open")
    changed = replace(parent, dividend_per_share=0.0)
    bars = tuple(changed if bar.security_id == parent.security_id else bar for bar in packet.bars)
    return replace(packet, bars=bars, spins=tuple(remaining)+(repair.add[0].terms(),))

_digest.source:
def _digest(value):
    return hashlib.sha256(json.dumps(value, sort_keys=True, separators=(",", ":"),
                                    allow_nan=False).encode()).hexdigest()

_session.source:
def _session(value):
    if date.fromisoformat(value).isoformat() != value or len(value) != 10:
        raise ValueError("canonical ISO session required")
    return value
